    constructor() {
        super();
        // Return proxy from constructor
        const callFn = () => {
            this.increment();
            return this.get();
        };
        
        return new Proxy(callFn, {
            get(target, prop) {
                return prop in this ? (this as any)[prop] : target[prop as any];
            },
            set(target, prop, value) {
                (this as any)[prop] = value;
                return true;
            }
        }) as any;
    }
